  final File root,files;final SQLiteDatabase db;final StorageBudgetR31 budget;
  Case()throws Exception{root=Files.createTempDirectory("r31-pin-admission-").toFile();files=new File(root,"files");need(files.mkdir(),"files");File databases=new File(root,"databases");need(databases.mkdir(),"databases");db=new SQLiteDatabase(DriverManager.getConnection("jdbc:sqlite:"+new File(databases,"main.db")));budget=new StorageBudgetR31(root,new StorageBudgetR31.Config(2048L<<20,4096L<<20,256L<<20,2L<<20,"EXPLICIT_ENGINEERING_LOGICAL_BYTES_NOT_ANDROID_ALLOCATION"),File::getUsableSpace);setup(db);}
